import { Component, forwardRef, Input, ViewEncapsulation } from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { ControlNameModule, espdAbstractInputComponentInjectionToken, EspdAbstractSizeableInputDirective } from 'espd-common/forms/api';
import { defaultDatePickerConfig } from 'espd-common/forms/date-picker/config';
import { InputScaffoldComponent } from 'espd-common/forms/input-scaffold';
import { BsDatepickerConfig, BsDatepickerModule } from 'ngx-bootstrap/datepicker';

@Component({
	selector: 'espd-date-picker',
	templateUrl: 'date-picker.component.html',
	imports: [
		BsDatepickerModule,
		ReactiveFormsModule,
		ControlNameModule,
		InputScaffoldComponent
	],
	styleUrls: ['date-picker.component.scss'],
	encapsulation: ViewEncapsulation.None, // ngx-bootstrap appends to body outside of the component
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => DatePickerComponent) }]
})
export class DatePickerComponent extends EspdAbstractSizeableInputDirective {

	@Input()
	public config?: Partial<BsDatepickerConfig>;

	public get datePickerConfig(): Partial<BsDatepickerConfig> {
		if (this.config) {
			return { ...defaultDatePickerConfig, ...this.config };
		} else {
			return defaultDatePickerConfig;
		}
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}