import { Component, forwardRef, HostListener, Input, OnChanges, OnDestroy, OnInit, SimpleChanges, ViewChild, ViewEncapsulation } from '@angular/core';
import { AbstractControl, ReactiveFormsModule } from '@angular/forms';
import { ButtonComponent } from 'espd-common/button';
import {
	ControlNameModule,
	espdAbstractInputComponentInjectionToken,
	EspdAbstractSizeableInputDirective,
	EspdFormControl, EspdFormGroup
} from 'espd-common/forms/api';
import { InputScaffoldComponent } from 'espd-common/forms/input-scaffold';
import { MessageModule } from 'espd-common/i18n';
import { BsDatepickerConfig, BsDaterangepickerDirective } from 'ngx-bootstrap/datepicker';
import { TimepickerConfig } from 'ngx-bootstrap/timepicker';
import { merge, Subscription } from 'rxjs';
import { filter, startWith } from 'rxjs/operators';
import { DatePickerComponent } from '../date-picker.component';
import { TimePickerModule } from '../time-picker/time-picker.module';

@Component({
	selector: 'espd-date-time-picker',
	templateUrl: 'date-time-picker.component.html',
	imports: [
		ReactiveFormsModule,
		ControlNameModule,
		InputScaffoldComponent,
		DatePickerComponent,
		TimePickerModule,
		MessageModule,
		ButtonComponent
	],
	styleUrls: ['date-time-picker.component.scss'],
	encapsulation: ViewEncapsulation.None,
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => DateTimePickerComponent) }]
})
export class DateTimePickerComponent extends EspdAbstractSizeableInputDirective implements OnInit, OnChanges, OnDestroy {

	@Input()
	public datePickerConfig?: Partial<BsDatepickerConfig>;

	@Input()
	public timePickerConfig?: Partial<TimepickerConfig>;

	@ViewChild('datePicker')
	private datePicker?: BsDaterangepickerDirective;

	public form = new EspdFormGroup({
		date: new EspdFormControl<Date>(null, this.validateControl()),
		time: new EspdFormControl<Date>(null, this.validateControl())
	});

	private subscription?: Subscription;
	private enableValueChangeListener: boolean = true;

	private isClearing: boolean = false;

	@HostListener('focusout')
	onFocusOut(): void {
		if (this.control) {
			this.control.markAsTouched();
		}
	}

	ngOnInit(): void {
		super.ngOnInit();
		if (this.control) {
			this.control.registerOnDisabledChange(disabled => {
				if (disabled) {
					this.form.disable({ emitEvent: false });
				} else {
					this.form.enable({ emitEvent: false });
				}
			});

			this.subscription = this.control.valueChanges
				.pipe(
					startWith(this.control.value),
					filter(() => this.enableValueChangeListener) // avoid an infinite loop with updateControlValue()
				)
				.subscribe(value => {
					setTimeout(() => {
						this.updateForm(value);
					});
				});

			merge(this.dateControl.valueChanges, this.timeControl.valueChanges).subscribe(() => this.updateControlValue());
		}
	}

	ngOnChanges(changes: SimpleChanges): void {
		super.ngOnChanges(changes);
		if (changes.datePickerConfig) {
			this.datePicker?.setConfig();
		}
	}

	ngOnDestroy(): void {
		super.ngOnDestroy();
		this.subscription?.unsubscribe();
	}

	public clear(): void {
		this.isClearing = true;
		this.dateControl.setValue(null);
		this.timeControl.setValue(null);
		this.isClearing = false;
		this.updateControlValue();
	}

	private get dateControl(): AbstractControl<Date | null> {
		return this.form.get('date')!;
	}

	private get timeControl(): AbstractControl<Date | null> {
		return this.form.get('time')!;
	}

	private updateControlValue() {
		if (this.control && !this.isClearing) {
			const date = this.dateControl.value;
			const time = this.timeControl.value;
			this.enableValueChangeListener = false;
			this.control.setValue(this.combineDateAndTime(date, time));
			this.enableValueChangeListener = true;
			this.control.markAsDirty();
			this.dateControl.updateValueAndValidity({ onlySelf: true, emitEvent: false });
			this.timeControl.updateValueAndValidity({ emitEvent: false });
		}
	}

	private updateForm(value: Date | null) {
		this.form.patchValue({
			date: value,
			time: value
		}, { emitEvent: false });
	}

	private combineDateAndTime(date: Date | null, time: Date | null): Date | null {
		if (!date && !time) {
			return null;
		} else if (!date) {
			date = new Date();
			this.dateControl.setValue(date);
		} else if (!time) {
			time = new Date();
			time.setHours(0, 0, 0, 0);
			this.timeControl.setValue(time);
		}
		if (!date || !time) {
			return null;
		}
		return new Date(date.getFullYear(), date.getMonth(), date.getDate(), time.getHours(), time.getMinutes(), time.getSeconds(), 0);
	}

	private validateControl() {
		const errors = { forStylesOnly: true };
		return () => this.control?.status === 'INVALID' ? errors : null;
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}