import { Component, forwardRef, Injector, Input, Optional } from '@angular/core';
import { espdAbstractInputComponentInjectionToken, EspdAbstractSizeableInputDirective } from 'espd-common/forms/api';
import { TimepickerConfig } from 'ngx-bootstrap/timepicker';

const defaultTimePickerConfig: Partial<TimepickerConfig> = {
	/** hours change step */
	hourStep: 1,
	/** minutes change step */
	minuteStep: 5,
	/** seconds change step */
	secondsStep: 10,
	/** if true hours and minutes fields will be readonly */
	readonlyInput: false,
	/** if true hours and minutes fields will be disabled */
	disabled: false,
	/** if true scroll inside hours and minutes inputs will change time */
	mousewheel: true,
	/** if true the values of hours and minutes can be changed using the up/down arrow keys on the keyboard */
	arrowkeys: true,
	/** if true spinner arrows above and below the inputs will be shown */
	showSpinners: true,
	/** if true meridian button will be shown */
	showMeridian: true,
	/** show minutes in timepicker */
	showMinutes: true,
	/** show seconds in timepicker */
	showSeconds: false,
	/** meridian labels based on locale */
	meridians: ['AM', 'PM'],
	/** placeholder for hours field in timepicker */
	hoursPlaceholder: 'HH',
	/** placeholder for minutes field in timepicker */
	minutesPlaceholder: 'MM',
	/** placeholder for seconds field in timepicker */
	secondsPlaceholder: 'SS'
};

@Component({
	selector: 'espd-time-picker',
	templateUrl: 'time-picker.component.html',
	styleUrls: ['time-picker.component.scss'],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => TimePickerComponent) }],
	standalone: false
})
export class TimePickerComponent extends EspdAbstractSizeableInputDirective {

	@Input()
	public config?: Partial<TimepickerConfig>;

	private defaults: Partial<TimepickerConfig> = defaultTimePickerConfig;

	constructor(
		@Optional() globalConfig: TimepickerConfig,
		injector: Injector
	) {
		super(injector);
		if (globalConfig) {
			this.defaults = { ...defaultTimePickerConfig, ...globalConfig };
		}
	}

	public get timePickerConfig(): Partial<TimepickerConfig> {
		if (this.config) {
			return { ...this.defaults, ...this.config };
		} else {
			return this.defaults;
		}
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}