import {
	ChangeDetectionStrategy,
	ChangeDetectorRef,
	Component,
	forwardRef
} from '@angular/core';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import {
	TimepickerActions,
	TimepickerComponent as NgxTimePickerComponent,
	TimepickerConfig,
	TimepickerStore
} from 'ngx-bootstrap/timepicker';
import { MessageService } from 'espd-common/i18n';

@Component({
    selector: 'espd-ngx-timepicker',
    changeDetection: ChangeDetectionStrategy.OnPush,
    templateUrl: 'ngx-time-picker.component.html',
    providers: [{
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => EspdNgxTimePickerComponent),
            multi: true
        }, TimepickerStore],
    styleUrls: ['ngx-time-picker.component.scss'],
    standalone: false
})
export class EspdNgxTimePickerComponent extends NgxTimePickerComponent {

	constructor(
		public messageService: MessageService,
		_config: TimepickerConfig,
		_cd: ChangeDetectorRef,
		_store: TimepickerStore,
		_timepickerActions: TimepickerActions
	) {
		super(_config, _cd, _store, _timepickerActions);
	}
}